<?php
$where=['p.status="publish"'];$params=[];$q=trim($_GET['q']??'');$category=trim($_GET['category']??'');$selected=null;
$cats=rows('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN product_categories pc ON pc.category_id=c.id LEFT JOIN products p ON p.id=pc.product_id AND p.status="publish" WHERE c.active=1 GROUP BY c.id ORDER BY c.sort_order,c.name');
if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ? OR p.short_description LIKE ?)';$params=array_fill(0,3,'%'.$q.'%');track('search',null,$q);}
if($category!==''){$selected=row('SELECT * FROM categories WHERE slug=? AND active=1',[$category]);if($selected){$ids=[(int)$selected['id']];do{$old=count($ids);foreach($cats as $c)if(in_array((int)$c['parent_id'],$ids)&&!in_array((int)$c['id'],$ids))$ids[]=(int)$c['id'];}while(count($ids)>$old);$where[]='EXISTS(SELECT 1 FROM product_categories pc WHERE pc.product_id=p.id AND pc.category_id IN ('.implode(',',$ids).'))';track('category_view',(int)$selected['id']);}else $where[]='1=0';}
foreach(['min'=>'>=','max'=>'<='] as $k=>$op)if(isset($_GET[$k])&&$_GET[$k]!==''&&is_numeric($_GET[$k])){$where[]="p.price $op ?";$params[]=max(0,(float)$_GET[$k]);}
$sorts=['rating'=>'(SELECT COALESCE(AVG(r.rating),0) FROM product_reviews r WHERE r.product_id=p.id AND r.status="published") DESC,p.id DESC','new'=>'p.created_at DESC,p.id DESC','price_asc'=>'p.price ASC,p.id ASC','price_desc'=>'p.price DESC,p.id DESC','name'=>'p.name ASC,p.id ASC','popularity'=>'(SELECT COALESCE(SUM(oi.quantity),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.product_id=p.id AND o.status NOT IN ("cancelled","refunded")) DESC,p.id DESC'];
$sort=$_GET['sort']??'new';if(!isset($sorts[$sort]))$sort='new';$size=(int)($_GET['count']??12);if(!in_array($size,[12,24,36]))$size=12;
$total=(int)scalar('SELECT COUNT(*) FROM products p WHERE '.implode(' AND ',$where),$params);$page=min(max(1,(int)($_GET['page']??1)),max(1,(int)ceil($total/$size)));
$list=rows('SELECT p.* FROM products p WHERE '.implode(' AND ',$where).' ORDER BY '.$sorts[$sort].' LIMIT '.$size.' OFFSET '.(($page-1)*$size),$params);
prime_product_reviews(array_column($list,'id'));
$priceLimit=(int)ceil((float)scalar('SELECT MAX(price) FROM products WHERE status="publish"'));
?>
<section class="tq-shop py-5"><div class="container"><div class="tq-shop-heading"><div><h1><?= h($selected['name']??'All Products') ?></h1><p>Browse medical equipment and supplies in our current catalog.</p></div><span><?= $total ?> products</span></div>
<div class="row g-4"><aside class="col-lg-3"><div class="offcanvas-lg offcanvas-start tq-filter-panel" tabindex="-1" id="shop-filter-sidebar" aria-labelledby="filter-title"><div class="offcanvas-header"><h4 id="filter-title">Filters</h4><button class="btn-close" type="button" data-bs-dismiss="offcanvas" data-bs-target="#shop-filter-sidebar" aria-label="Close filters"></button></div><div class="offcanvas-body"><form id="shop-filters" class="store-form" action="<?= url('shop-grid.php') ?>"><div class="tq-filter-heading"><h4>Filters</h4><a href="<?= url('shop-grid.php') ?>">Clear all</a></div><label for="shop-search">Search products</label><input id="shop-search" name="q" placeholder="Product name or SKU" value="<?= h($q) ?>"><label for="shop-category">Categories</label><select id="shop-category" name="category"><option value="">All categories</option><?php foreach($cats as $c): ?><option value="<?= h($c['slug']) ?>" <?= $c['slug']===$category?'selected':'' ?>><?= $c['parent_id']?'— ':'' ?><?= h(html_entity_decode($c['name'],ENT_QUOTES,'UTF-8')) ?></option><?php endforeach; ?></select>
<div class="tq-category-filter"><?php foreach($cats as $c): if($c['parent_id'])continue;$count=(int)$c['product_count'];foreach($cats as $child)if($child['parent_id']==$c['id'])$count+=(int)$child['product_count']; ?><details <?= $selected&&($selected['id']==$c['id']||$selected['parent_id']==$c['id'])?'open':'' ?>><summary><a href="?<?= h(http_build_query(array_merge($_GET,['category'=>$c['slug'],'page'=>1]))) ?>"><?= h(html_entity_decode($c['name'],ENT_QUOTES,'UTF-8')) ?></a><span><?= $count ?></span></summary><?php foreach($cats as $child):if($child['parent_id']!=$c['id'])continue; ?><a href="?<?= h(http_build_query(array_merge($_GET,['category'=>$child['slug'],'page'=>1]))) ?>"><?= h(html_entity_decode($child['name'],ENT_QUOTES,'UTF-8')) ?> <small><?= $child['product_count'] ?></small></a><?php endforeach; ?></details><?php endforeach; ?></div>
<h5 class="mt-4 mb-3">Price range (<?= h(setting('currency','KES')) ?>)</h5><div class="row g-2"><div class="col-6"><label for="min">Minimum</label><input id="min" type="number" name="min" min="0" step="0.01" value="<?= h($_GET['min']??'') ?>"></div><div class="col-6"><label for="max">Maximum</label><input id="max" type="number" name="max" min="0" step="0.01" value="<?= h($_GET['max']??'') ?>"></div></div><label for="price-range">Maximum price</label><input id="price-range" class="tq-price-range" type="range" min="0" max="<?= max(1,$priceLimit) ?>" value="<?= h($_GET['max']??$priceLimit) ?>"><button class="theme-btn w-100 mt-3">Apply filters</button></form></div></div></aside>
<div class="col-lg-9"><div class="tq-shop-toolbar"><button type="button" class="btn btn-outline-secondary d-lg-none" data-bs-toggle="offcanvas" data-bs-target="#shop-filter-sidebar" aria-controls="shop-filter-sidebar" aria-label="Filters"><i aria-hidden="true" class="far fa-sliders"></i> Filters</button><label>Sort by <select name="sort" form="shop-filters" id="shop-sort" data-shop-submit><?php foreach(['rating'=>'Average rating','new'=>'Newest arrivals','popularity'=>'Best selling','price_asc'=>'Price: low to high','price_desc'=>'Price: high to low','name'=>'Name'] as $key=>$label): ?><option value="<?= $key ?>" <?= $sort===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Show <select name="count" form="shop-filters" data-shop-submit><?php foreach([12,24,36] as $n): ?><option <?= $size===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><div class="tq-layout-buttons" aria-label="Product layout"><button class="btn active" type="button" data-shop-layout="grid" aria-label="Grid view" aria-pressed="true"><i class="far fa-grid-2"></i></button><button class="btn" type="button" data-shop-layout="list" aria-label="List view" aria-pressed="false"><i class="far fa-list"></i></button></div></div>
<p class="tq-results-summary">Showing <span id="shop-visible-count"><?= count($list) ?></span> of <?= $total ?> products</p>
<div id="shop-products" class="row store-grid tq-shop-products" data-page="<?= $page ?>" data-pages="<?= max(1,(int)ceil($total/$size)) ?>"><?php foreach($list as $product)product_card($product);if(!$list): ?><div class="col-12"><p>No products match your selection. <a href="<?= url('shop-grid.php') ?>">Clear filters</a></p></div><?php endif; ?></div>
<div id="shop-load-sentinel" class="tq-load-more"><p id="shop-load-status" role="status" aria-live="polite"></p><button class="theme-btn" id="shop-load-more" type="button" hidden>Load more products</button></div><div id="shop-pagination"><?php pagination($total,$size,$page); ?></div>
</div></div></div></section>
